#include <string.h>

// Function to check if a file extension is dangerous
static bool IsDangerousExtension(const char* file_path) {
    const char* dangerous_extensions[] = {".exe", ".bat", ".sh", ".dll"};
    size_t num_extensions = sizeof(dangerous_extensions) / sizeof(dangerous_extensions[0]);

    // Find the last dot in the file path
    const char* last_dot = strrchr(file_path, '.');
    if (!last_dot) {
        return false;
    }

    // Check if the extension matches any dangerous extension
    for (size_t i = 0; i < num_extensions; ++i) {
        if (strcmp(last_dot, dangerous_extensions[i]) == 0) {
            return true;
        }
    }

    return false;
}

// Function to determine if a download is dangerous
bool IsDangerousDownload(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Check if the download is an extension without approval
    if (download.is_extension && !download.is_approved) {
        return true;
    }

    // Check if the file has a dangerous extension
    if (IsDangerousExtension(suggested_path)) {
        return true;
    }

    // If the user has not interacted with the page and hasn't visited the referrer before, it's dangerous
    if (!download.user_gesture && !visited_referrer_before) {
        return true;
    }

    return false;
}
